from itertools import combinations, product

def brute_force_pentagons(n):
    count = 0
    for combo in combinations(range(n), 5):
        x = list(combo)
        d = []
        for i in range(4):
            d.append(x[i+1] - x[i])
        d.append(n - (x[4] - x[0]))
        s = [d[i] + d[(i+1)%5] for i in range(5)]
        acute = sum(1 for val in s if val > n/2)
        if acute == 2:
            count += 1
    return count

